// src/serialization/safetensors.rs
use serde::{Deserialize, Serialize};
use std::collections::BTreeMap; // BTreeMap for deterministic ordering!
use std::fs;
use std::path::Path; #[derive(Debug, Clone, Serialize, Deserialize)]
pub struct TensorMetadata { pub dtype: String, pub shape: Vec<usize>, pub data_offsets: [usize; 2],
} pub type SafeTensorsMetadata = BTreeMap<String, TensorMetadata>; pub fn save_safetensors<P: AsRef<Path>>( path: P, tensors: BTreeMap<String, (Vec<f32>, Vec<usize>)>,
) -> Result<(), String> { let mut metadata = SafeTensorsMetadata::new(); let mut raw_data = Vec::new(); let mut current_offset = 0; // Process tensors (BTreeMap provides sorted iteration) for (name, (data, shape)) in &tensors { let start_offset = current_offset; let data_size = data.len() * 4; // F32 = 4 bytes let end_offset = current_offset + data_size; metadata.insert( name.clone(), TensorMetadata { dtype: "F32".to_string(), shape: shape.clone(), data_offsets: [start_offset, end_offset], }, ); // Write F32 data (little-endian) for &value in data { raw_data.extend_from_slice(&value.to_le_bytes()); } current_offset = end_offset; } // Serialize metadata to JSON let metadata_json = serde_json::to_string(&metadata) .map_err(|e| format!("JSON serialization failed: {}", e))?; let metadata_bytes = metadata_json.as_bytes(); let metadata_len = metadata_bytes.len() as u64; // Write SafeTensors format let mut output = Vec::new(); output.extend_from_slice(&metadata_len.to_le_bytes()); // 8-byte header output.extend_from_slice(metadata_bytes); // JSON metadata output.extend_from_slice(&raw_data); // Tensor data fs::write(path, output).map_err(|e| format!("File write failed: {}", e))?; Ok(())
} Key Design Decision : Using BTreeMap instead of HashMap ensures deterministic serialization (sorted keys).

