//! Complete .apr workflow: train, save, encrypt, deploy
//!
//! cargo run --example apr_workflow use aprender::prelude::*;
use aprender::format::{ save, load, save_encrypted, load_encrypted, save_for_recipient, load_as_recipient, ModelType, SaveOptions,
};
use aprender::tree::DecisionTreeClassifier; fn main() -> Result<(), Box<dyn std::error::Error>> { // 1. Train a model let (x_train, y_train) = load_iris_dataset()?; let mut model = DecisionTreeClassifier::new().with_max_depth(5); model.fit(&x_train, &y_train)?; println!("Model trained. Accuracy: {:.2}%", model.score(&x_train, &y_train)? * 100.0); // 2. Save with metadata let options = SaveOptions::default() .with_name("iris-classifier") .with_description("Decision tree for Iris classification") .with_author("ML Team"); save(&model, ModelType::DecisionTree, "model.apr", options.clone())?; println!("Saved to model.apr"); // 3. Save encrypted (password) save_encrypted(&model, ModelType::DecisionTree, "model-encrypted.apr", options.clone(), "secret-password")?; println!("Saved encrypted to model-encrypted.apr"); // 4. Load and verify let loaded: DecisionTreeClassifier = load("model.apr", ModelType::DecisionTree)?; assert_eq!(loaded.score(&x_train, &y_train)?, model.score(&x_train, &y_train)?); println!("Loaded and verified!"); // 5. Load encrypted let loaded_enc: DecisionTreeClassifier = load_encrypted("model-encrypted.apr", ModelType::DecisionTree, "secret-password")?; println!("Loaded encrypted model!"); // 6. Demonstrate embedded deployment println!("\nFor embedded deployment, add to your binary:"); println!(" const MODEL: &[u8] = include_bytes!(\"model.apr\");"); println!(" let model: DecisionTreeClassifier = load_from_bytes(MODEL, ModelType::DecisionTree)?;"); // Cleanup std::fs::remove_file("model.apr")?; std::fs::remove_file("model-encrypted.apr")?; Ok(())
} fn load_iris_dataset() -> Result<(Matrix<f32>, Vec<usize>), Box<dyn std::error::Error>> { // Simplified Iris dataset let x = Matrix::from_vec(12, 4, vec![ 5.1, 3.5, 1.4, 0.2, // setosa 4.9, 3.0, 1.4, 0.2, 7.0, 3.2, 4.7, 1.4, // versicolor 6.4, 3.2, 4.5, 1.5, 6.3, 3.3, 6.0, 2.5, // virginica 5.8, 2.7, 5.1, 1.9, 5.0, 3.4, 1.5, 0.2, // setosa 4.4, 2.9, 1.4, 0.2, 6.9, 3.1, 4.9, 1.5, // versicolor 5.5, 2.3, 4.0, 1.3, 6.5, 3.0, 5.8, 2.2, // virginica 7.6, 3.0, 6.6, 2.1, ])?; let y = vec![0, 0, 1, 1, 2, 2, 0, 0, 1, 1, 2, 2]; Ok((x, y))
}

