Implemented agglomerative clustering algorithm in src/cluster/mod.rs: 1. Linkage Enum and Merge Structure: #[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub enum Linkage { Single, // Minimum distance Complete, // Maximum distance Average, // Mean distance Ward, // Minimize variance
} #[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Merge { pub clusters: (usize, usize), pub distance: f32, pub size: usize,
} 2. Main Algorithm: impl AgglomerativeClustering { pub fn new(n_clusters: usize, linkage: Linkage) -> Self { Self { n_clusters, linkage, labels: None, dendrogram: None, } } fn pairwise_distances(&self, x: &Matrix<f32>) -> Vec<Vec<f32>> { // Calculate all pairwise Euclidean distances let n_samples = x.shape().0; let mut distances = vec![vec![0.0; n_samples]; n_samples]; for i in 0..n_samples { for j in (i + 1)..n_samples { let dist = self.euclidean_distance(x, i, j); distances[i][j] = dist; distances[j][i] = dist; } } distances } fn find_closest_clusters( &self, distances: &[Vec<f32>], active: &[bool], ) -> (usize, usize, f32) { // Find minimum distance between active clusters // ... } fn update_distances( &self, x: &Matrix<f32>, distances: &mut [Vec<f32>], clusters: &[Vec<usize>], merged_idx: usize, other_idx: usize, ) { // Update distances based on linkage method let dist = match self.linkage { Linkage::Single => { /* minimum distance */ }, Linkage::Complete => { /* maximum distance */ }, Linkage::Average => { /* average distance */ }, Linkage::Ward => { /* Ward's method */ }, }; // ... }
} 3. UnsupervisedEstimator Implementation: impl UnsupervisedEstimator for AgglomerativeClustering { type Labels = Vec<usize>; fn fit(&mut self, x: &Matrix<f32>) -> Result<()> { let n_samples = x.shape().0; // Initialize: each point is its own cluster let mut clusters: Vec<Vec<usize>> = (0..n_samples).map(|i| vec![i]).collect(); let mut active = vec![true; n_samples]; let mut dendrogram = Vec::new(); // Calculate initial distances let mut distances = self.pairwise_distances(x); // Merge until reaching target number of clusters while clusters.iter().filter(|c| !c.is_empty()).count() > self.n_clusters { // Find closest pair let (i, j, dist) = self.find_closest_clusters(&distances, &active); // Merge clusters clusters[i].extend(&clusters[j]); clusters[j].clear(); active[j] = false; // Record merge dendrogram.push(Merge { clusters: (i, j), distance: dist, size: clusters[i].len(), }); // Update distances for k in 0..n_samples { if k != i && active[k] { self.update_distances(x, &mut distances, &clusters, i, k); } } } // Assign final labels // ... Ok(()) } fn predict(&self, _x: &Matrix<f32>) -> Self::Labels { self.labels().clone() }
} Verification: $ cargo test
