} impl NgramTable { fn with_n(n: usize) -> Self { Self { table: HashMap::new(), n: n.max(2) } } fn observe(&mut self, context: &str, next_token: &str) { self.table .entry(context.to_string()) .or_default() .entry(next_token.to_string()) .and_modify(|c| *c += 1) .or_insert(1); } /// Train on a single command fn train_command(&mut self, command: &str) { let tokens: Vec<&str> = command.split_whitespace().collect(); if tokens.is_empty() { return; } // Empty context predicts first token self.observe("", tokens[0]); // Build n-grams from token sequence for i in 0..tokens.len() { let context_start = i.saturating_sub(self.n - 1); let context = tokens[context_start..=i].join(" "); if i + 1 < tokens.len() { self.observe(&context, tokens[i + 1]); } } } fn predict(&self, context: &str) -> Vec<(String, f32)> { let Some(counts) = self.table.get(context) else { return vec![]; }; let total: u32 = counts.values().sum(); let mut probs: Vec<_> = counts .iter() .map(|(t, c)| (t.clone(), *c as f32 / total as f32)) .collect(); probs.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap()); probs }
