use std::collections::HashMap; /// Trie node for prefix matching
#[derive(Default)]
struct TrieNode { children: HashMap<char, TrieNode>, is_end: bool, count: u32,
} /// Trie for fast prefix-based command lookup
#[derive(Default)]
struct Trie { root: TrieNode,
} impl Trie { fn new() -> Self { Self::default() } fn insert(&mut self, word: &str) { let mut node = &mut self.root; for ch in word.chars() { node = node.children.entry(ch).or_default(); } node.is_end = true; node.count += 1; } /// Find completions for prefix, sorted by frequency fn find_prefix(&self, prefix: &str, limit: usize) -> Vec<(String, u32)> { // Navigate to prefix node let mut node = &self.root; for ch in prefix.chars() { match node.children.get(&ch) { Some(n) => node = n, None => return vec![], } } // Collect all completions let mut results = Vec::new(); self.collect(node, prefix.to_string(), &mut results, limit * 10); // Sort by frequency and take top N results.sort_by(|a, b| b.1.cmp(&a.1)); results.truncate(limit); results } fn collect(&self, node: &TrieNode, current: String, results: &mut Vec<(String, u32)>, limit: usize) { if results.len() >= limit { return; } if node.is_end { results.push((current.clone(), node.count)); } for (ch, child) in &node.children { let mut next = current.clone(); next.push(*ch); self.collect(child, next, results, limit); } }
} // Test: Basic insertion and lookup
let mut trie = Trie::new();
trie.insert("git status");
trie.insert("git commit");
trie.insert("git push"); let results = trie.find_prefix("git ", 10);
assert_eq!(results.len(), 3); // Test: Frequency ordering
let mut trie = Trie::new();
trie.insert("git status");
trie.insert("git status");
trie.insert("git status");
trie.insert("git commit"); let results = trie.find_prefix("git ", 10);
assert_eq!(results[0].0, "git status");
assert_eq!(results[0].1, 3); // Appeared 3 times // Test: No match returns empty
