} impl DecayingModel { fn new(decay: f32) -> Self { Self { ngrams: HashMap::new(), decay: decay.clamp(0.9, 0.999), } } fn observe(&mut self, context: &str, token: &str) { // Decay all existing counts first for counts in self.ngrams.values_mut() { for count in counts.values_mut() { *count *= self.decay; } } // Add new observation with weight 1.0 self.ngrams .entry(context.to_string()) .or_default() .entry(token.to_string()) .and_modify(|c| *c += 1.0) .or_insert(1.0); } fn predict(&self, context: &str) -> Vec<(String, f32)> { let Some(counts) = self.ngrams.get(context) else { return vec![]; }; let total: f32 = counts.values().sum(); if total < 0.001 { return vec![]; } let mut probs: Vec<_> = counts .iter() .map(|(t, c)| (t.clone(), *c / total)) .collect(); probs.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap()); probs }
} // Test decay behavior
