} impl PrivacyFilter { fn new() -> Self { Self { sensitive_patterns: vec![ "password".to_string(), "passwd".to_string(), "secret".to_string(), "token".to_string(), "api_key".to_string(), "AWS_SECRET".to_string(), "GITHUB_TOKEN".to_string(), "Authorization:".to_string(), ], } } fn is_safe(&self, command: &str) -> bool { let lower = command.to_lowercase(); // Check sensitive patterns for pattern in &self.sensitive_patterns { if lower.contains(&pattern.to_lowercase()) { return false; } } // Skip history manipulation if command.starts_with("history") || command.starts_with("fc ") { return false; } // Skip very short commands if command.len() < 2 { return false; } true } fn filter(&self, commands: Vec<String>) -> Vec<String> { commands.into_iter().filter(|c| self.is_safe(c)).collect() }
} let filter = PrivacyFilter::new(); // Safe commands pass through
assert!(filter.is_safe("git push origin main"));
assert!(filter.is_safe("cargo build --release")); // Sensitive commands are blocked
assert!(!filter.is_safe("export API_KEY=secret123"));
assert!(!filter.is_safe("curl -H 'Authorization: Bearer token'"));
assert!(!filter.is_safe("echo $PASSWORD")); // History manipulation blocked
assert!(!filter.is_safe("history -c"));
assert!(!filter.is_safe("fc -l")); // Filter a batch
let commands = vec![ "git status".to_string(), "export SECRET=abc".to_string(), "cargo test".to_string(),
];
let safe = filter.filter(commands);
assert_eq!(safe.len(), 2);
assert_eq!(safe[0], "git status");
assert_eq!(safe[1], "cargo test");

