//! Complete shell history model with .apr persistence
//!
//! cargo run --example shell_history_model use aprender::format::{save, load, ModelType, SaveOptions};
use serde::{Serialize, Deserialize};
use std::collections::HashMap;
use std::path::Path; #[derive(Serialize, Deserialize, Default)]
pub struct ShellHistoryModel { n: usize, ngrams: HashMap<String, HashMap<String, u32>>, command_freq: HashMap<String, u32>, total_commands: usize,
} impl ShellHistoryModel { pub fn new(n: usize) -> Self { Self { n: n.clamp(2, 5), ..Default::default() } } pub fn train(&mut self, commands: &[String]) { for cmd in commands { self.train_command(cmd); } } fn train_command(&mut self, cmd: &str) { self.total_commands += 1; *self.command_freq.entry(cmd.to_string()).or_insert(0) += 1; let tokens: Vec<&str> = cmd.split_whitespace().collect(); if tokens.is_empty() { return; } // Empty context → first token self.observe("", tokens[0]); // Build n-grams for i in 0..tokens.len() { let start = i.saturating_sub(self.n - 1); let context = tokens[start..=i].join(" "); if i + 1 < tokens.len() { self.observe(&context, tokens[i + 1]); } } } fn observe(&mut self, context: &str, token: &str) { self.ngrams .entry(context.to_string()) .or_default() .entry(token.to_string()) .and_modify(|c| *c += 1) .or_insert(1); } pub fn suggest(&self, prefix: &str, count: usize) -> Vec<(String, f32)> { let tokens: Vec<&str> = prefix.trim().split_whitespace().collect(); if tokens.is_empty() { return self.top_first_tokens(count); } let start = tokens.len().saturating_sub(self.n - 1); let context = tokens[start..].join(" "); let Some(next_tokens) = self.ngrams.get(&context) else { return vec![]; }; let total: u32 = next_tokens.values().sum(); let mut suggestions: Vec<_> = next_tokens .iter() .map(|(token, count)| { let completion = format!("{} {}", prefix, token); let prob = *count as f32 / total as f32; (completion, prob) }) .collect(); suggestions.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap()); suggestions.truncate(count); suggestions } fn top_first_tokens(&self, count: usize) -> Vec<(String, f32)> { let Some(firsts) = self.ngrams.get("") else { return vec![]; }; let total: u32 = firsts.values().sum(); let mut results: Vec<_> = firsts .iter() .map(|(t, c)| (t.clone(), *c as f32 / total as f32)) .collect(); results.sort_by(|a, b| b.1.partial_cmp(&a.1).unwrap()); results.truncate(count); results } pub fn save_to_apr(&self, path: &Path) -> Result<(), aprender::error::AprenderError> { let options = SaveOptions::default() .with_name("shell-history-model") .with_description(&format!( "{}-gram model trained on {} commands", self.n, self.total_commands )); save(self, ModelType::Custom, path, options) } pub fn load_from_apr(path: &Path) -> Result<Self, aprender::error::AprenderError> { load(path, ModelType::Custom) } pub fn stats(&self) -> ModelStats { ModelStats { n: self.n, total_commands: self.total_commands, unique_commands: self.command_freq.len(), ngram_count: self.ngrams.values().map(|m| m.len()).sum(), } }
} #[derive(Debug)]
pub struct ModelStats { pub n: usize, pub total_commands: usize, pub unique_commands: usize, pub ngram_count: usize,
} fn main() -> Result<(), Box<dyn std::error::Error>> { // Simulate shell history let history = vec![ "git status", "git add .", "git commit -m fix", "git push", "git status", "git log --oneline", "cargo build", "cargo test", "cargo build --release", "cargo clippy", ] .into_iter() .map(String::from) .collect::<Vec<_>>(); // Train model let mut model = ShellHistoryModel::new(3); model.train(&history); // Show stats let stats = model.stats(); println!("Model Statistics:"); println!(" N-gram size: {}", stats.n); println!(" Total commands: {}", stats.total_commands); println!(" Unique commands: {}", stats.unique_commands); println!(" N-gram count: {}", stats.ngram_count); // Test suggestions println!("\nSuggestions for 'git ':"); for (suggestion, prob) in model.suggest("git ", 5) { println!(" {:.1}% {}", prob * 100.0, suggestion); } println!("\nSuggestions for 'cargo ':"); for (suggestion, prob) in model.suggest("cargo ", 5) { println!(" {:.1}% {}", prob * 100.0, suggestion); } // Save to .apr let path = std::path::Path::new("shell_history.apr"); model.save_to_apr(path)?; println!("\nModel saved to: {}", path.display()); // Reload and verify let loaded = ShellHistoryModel::load_from_apr(path)?; assert_eq!(loaded.total_commands, model.total_commands); println!("Model reloaded successfully!"); // Cleanup std::fs::remove_file(path)?; Ok(())
}

