Principle : All ML algorithms implement standard traits defining consistent interfaces. /// Supervised learning: classification and regression
pub trait Estimator { fn fit(&mut self, x: &Matrix<f32>, y: &Vector<f32>) -> Result<()>; fn predict(&self, x: &Matrix<f32>) -> Vector<f32>; fn score(&self, x: &Matrix<f32>, y: &Vector<f32>) -> f32;
} /// Unsupervised learning: clustering, dimensionality reduction
pub trait UnsupervisedEstimator { type Labels; fn fit(&mut self, x: &Matrix<f32>) -> Result<()>; fn predict(&self, x: &Matrix<f32>) -> Self::Labels;
} /// Data transformation: scalers, encoders
pub trait Transformer { fn fit(&mut self, x: &Matrix<f32>) -> Result<()>; fn transform(&self, x: &Matrix<f32>) -> Result<Matrix<f32>>; fn fit_transform(&mut self, x: &Matrix<f32>) -> Result<Matrix<f32>>;
} Benefits : Consistency : All models work the same way Generic programming : Write code that works with any Estimator Discoverability : IDE autocomplete shows all methods Documentation : Trait docs explain the contract

