Aprender uses row-major storage (like C, NumPy): // Row-major: [row0_col0, row0_col1, ..., row1_col0, row1_col1, ...]
pub struct Matrix<T> { data: Vec<T>, // Flat array, row-major order rows: usize, cols: usize,
} // ✅ Cache-friendly: iterate rows (sequential access)
for i in 0..matrix.n_rows() { for j in 0..matrix.n_cols() { sum += matrix.get(i, j); // Sequential in memory }
} // ❌ Cache-unfriendly: iterate columns (strided access)
for j in 0..matrix.n_cols() { for i in 0..matrix.n_rows() { sum += matrix.get(i, j); // Jumps by `cols` stride }
} Benchmark (1000×1000 matrix): Row-major iteration: 2.1 ms Column-major iteration: 8.7 ms 4x slowdown from cache misses!

