Naive summation accumulates O(n·ε) floating-point error on large graphs. Aprender uses Kahan compensated summation : let mut sum = 0.0;
let mut c = 0.0; // Compensation term for value in values { let y = value - c; let t = sum + y; c = (t - sum) - y; // Recover low-order bits sum = t;
