pub fn train_test_split( x: &Matrix<f32>, y: &Vector<f32>, test_size: f32, random_state: Option<u64>,
) -> Result<(Matrix<f32>, Matrix<f32>, Vector<f32>, Vector<f32>), String> { if test_size <= 0.0 || test_size >= 1.0 { return Err("test_size must be between 0 and 1 (exclusive)".to_string()); } let n_samples = x.shape().0; if n_samples != y.len() { return Err("x and y must have same number of samples".to_string()); } let n_test = (n_samples as f32 * test_size).round() as usize; let n_train = n_samples - n_test; let mut indices: Vec<usize> = (0..n_samples).collect(); if let Some(seed) = random_state { let mut rng = rand::rngs::StdRng::seed_from_u64(seed); indices.shuffle(&mut rng); } else { indices.shuffle(&mut rand::thread_rng()); } let train_idx = &indices[..n_train]; let test_idx = &indices[n_train..]; let (x_train, y_train) = extract_samples(x, y, train_idx); let (x_test, y_test) = extract_samples(x, y, test_idx); Ok((x_train, x_test, y_train, y_test))
} fn extract_samples( x: &Matrix<f32>, y: &Vector<f32>, indices: &[usize],
) -> (Matrix<f32>, Vector<f32>) { let n_features = x.shape().1; let mut x_data = Vec::with_capacity(indices.len() * n_features); let mut y_data = Vec::with_capacity(indices.len()); for &idx in indices { for j in 0..n_features { x_data.push(x.get(idx, j)); } y_data.push(y.as_slice()[idx]); } let x_subset = Matrix::from_vec(indices.len(), n_features, x_data) .expect("Failed to create matrix"); let y_subset = Vector::from_vec(y_data); (x_subset, y_subset)
